    """
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    """

    def __init__(self, name, rooms):
        """
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        """
        self.name = name
        # Make a copy to avoid external mutation
        self.available_rooms = dict(rooms)
        # Structure: {room_type: {guest_name: number}}
        self.booked_rooms = {rt: {} for rt in rooms}

    def book_room(self, room_type, room_number, name):
        """
        Book rooms for a guest if available.
        """
        # Check if room_type exists
        if room_type not in self.available_rooms:
            return False
        available = self.available_rooms[room_type]
        if available == 0:
            return False
        if room_number > available:
            return available
        # Booking is possible
        self.available_rooms[room_type] -= room_number
        # Initialize booked_rooms for this room_type if not present
        if room_type not in self.booked_rooms:
            self.booked_rooms[room_type] = {}
        # Accumulate bookings for the same guest
        if name in self.booked_rooms[room_type]:
            self.booked_rooms[room_type][name] += room_number
        else:
            self.booked_rooms[room_type][name] = room_number
        return 'Success!'

    def check_in(self, room_type, room_number, name):
        """
        Guest checks in for booked rooms.
        """
        # Check if room_type is in booked_rooms and guest has bookings
        if room_type not in self.booked_rooms:
            return False
        if name not in self.booked_rooms[room_type]:
            return False
        booked = self.booked_rooms[room_type][name]
        if room_number > booked:
            return False
        # Partial check-in: reduce booked_rooms count
        if room_number == booked:
            del self.booked_rooms[room_type][name]
        else:
            self.booked_rooms[room_type][name] -= room_number
        # Optionally, clean up empty dict
        # (not required, but keeps dict tidy)
        # if not self.booked_rooms[room_type]:
        #     del self.booked_rooms[room_type]
        return None  # As per docstring, no explicit return on success

    def check_out(self, room_type, room_number):
        """
        Rooms are checked out and returned to available_rooms.
        """
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        """
        Get number of available rooms for a type.
        """
        return self.available_rooms.get(room_type, 0)

class JobMarketplace:
    """
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    """

    def __init__(self):
        self.job_listings = []
        self.resumes = []

    def post_job(self, job_title, company, requirements):
        """
        This function is used to publish positions,and add the position information to the job_listings list.
        """
        job = {
            'job_title': job_title,
            'company': company,
            'requirements': requirements
        }
        self.job_listings.append(job)

    def remove_job(self, job):
        """
        This function is used to remove positions,and remove the position information from the job_listings list.
        """
        if job in self.job_listings:
            self.job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        """
        This function is used to submit resumes,and add the resume information to the resumes list.
        """
        resume = {
            'name': name,
            'skills': skills,
            'experience': experience
        }
        self.resumes.append(resume)

    def withdraw_resume(self, resume):
        """
        This function is used to withdraw resumes,and remove the resume information from the resumes list.
        """
        if resume in self.resumes:
            self.resumes.remove(resume)

    def search_jobs(self, criteria):
        """
        This function is used to search for positions,and return the position information that meets the requirements.
        """
        result = []
        for job in self.job_listings:
            # If criteria matches any requirement
            if any(criteria == req for req in job.get('requirements', [])):
                result.append(job)
        return result

    def get_job_applicants(self, job):
        """
        This function is used to obtain candidate information,and return the candidate information that meets the requirements by calling the matches_requirements function.
        """
        requirements = job.get('requirements', [])
        applicants = []
        for resume in self.resumes:
            if self.matches_requirements(resume, requirements):
                applicants.append(resume)
        return applicants

    @staticmethod
    def matches_requirements(resume, requirements):
        """
        Helper function to check if a resume matches all requirements.
        """
        resume_skills = resume.get('skills', [])
        # All requirements must be in resume_skills
        return all(req in resume_skills for req in requirements)

import random

class MinesweeperGame:
    """
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    """

    def __init__(self, n, k) -> None:
        """
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        :param n: The size of the board, int.
        :param k: The number of mines, int.
        """
        self.n = n
        self.k = k
        self.minesweeper_map = self.generate_mine_sweeper_map()
        self.player_map = self.generate_playerMap()
        self.score = 0

    def generate_mine_sweeper_map(self):
        """
        Generates a minesweeper map with the given size of the board and the number of mines,the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'X' represents the mine,other numbers represent the number of mines around the position.
        :return: The minesweeper map, list.
        """
        n, k = self.n, self.k
        # Initialize empty board
        board = [[0 for _ in range(n)] for _ in range(n)]
        # Place k mines randomly
        positions = [(i, j) for i in range(n) for j in range(n)]
        mine_positions = random.sample(positions, k)
        for (i, j) in mine_positions:
            board[i][j] = 'X'
        # For each cell, if not a mine, count adjacent mines
        for i in range(n):
            for j in range(n):
                if board[i][j] == 'X':
                    continue
                count = 0
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < n and 0 <= nj < n:
                            if board[ni][nj] == 'X':
                                count += 1
                board[i][j] = count
        return board

    def generate_playerMap(self):
        """
        Generates a player map with the given size of the board, the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'-' represents the unknown position.
        :return: The player map, list.
        """
        n = self.n
        return [['-' for _ in range(n)] for _ in range(n)]

    def check_won(self, map):
        """
        Checks whether the player has won the game,if there are just mines in the player map,return True,otherwise return False.
        :return: True if the player has won the game, False otherwise.
        """
        n = self.n
        for i in range(n):
            for j in range(n):
                if map[i][j] == '-' and self.minesweeper_map[i][j] != 'X':
                    return False
        return True

    def sweep(self, x, y):
        """
        Sweeps the given position.
        :param x: The x coordinate of the position, int.
        :param y: The y coordinate of the position, int.
        :return: True if the player has won the game, False otherwise,if the game still continues, return the player map, list.
        """
        n = self.n
        if not (0 <= x < n and 0 <= y < n):
            # Out of bounds, ignore
            return self.player_map

        if self.player_map[x][y] != '-':
            # Already revealed
            return self.player_map

        if self.minesweeper_map[x][y] == 'X':
            self.player_map[x][y] = 'X'
            return False  # Game over

        # Reveal cell
        def flood_fill(i, j):
            if not (0 <= i < n and 0 <= j < n):
                return
            if self.player_map[i][j] != '-':
                return
            self.player_map[i][j] = self.minesweeper_map[i][j]
            if self.minesweeper_map[i][j] == 0:
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        ni, nj = i + dx, j + dy
                        flood_fill(ni, nj)

        flood_fill(x, y)

        if self.check_won(self.player_map):
            return True
        else:
            return self.player_map

class NumberConverter:
    """
    The class allows to convert decimal to binary, octal and hexadecimal respectively and contrarily.
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer.")
        if decimal_num == 0:
            return '0'
        prefix = '-' if decimal_num < 0 else ''
        return prefix + bin(abs(decimal_num))[2:]

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        """
        if not isinstance(binary_num, str):
            raise TypeError("Input must be a string.")
        binary_num = binary_num.strip()
        if binary_num.startswith('-'):
            return -int(binary_num[1:], 2)
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer.")
        if decimal_num == 0:
            return '0'
        prefix = '-' if decimal_num < 0 else ''
        return prefix + oct(abs(decimal_num))[2:]

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        """
        if not isinstance(octal_num, str):
            raise TypeError("Input must be a string.")
        octal_num = octal_num.strip()
        if octal_num.startswith('-'):
            return -int(octal_num[1:], 8)
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("Input must be an integer.")
        if decimal_num == 0:
            return '0'
        prefix = '-' if decimal_num < 0 else ''
        return prefix + hex(abs(decimal_num))[2:].lower()

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        """
        if not isinstance(hex_num, str):
            raise TypeError("Input must be a string.")
        hex_num = hex_num.strip()
        if hex_num.startswith('-'):
            return -int(hex_num[1:], 16)
        return int(hex_num, 16)

class NumberWordFormatter:
    """
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    """

    def __init__(self):
        """
        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        """
        assert len(s) == 2
        n = int(s)
        if n == 0:
            return ""
        if s[0] == "0":
            return self.NUMBER[int(s[1])]
        elif s[0] == "1":
            return self.NUMBER_TEEN[int(s[1])]
        else:
            tens = self.NUMBER_TEN[int(s[0]) - 1]
            units = self.NUMBER[int(s[1])]
            if units:
                return tens + " " + units
            else:
                return tens

    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        """
        assert len(s) == 3
        n = int(s)
        if n == 0:
            return ""
        words = []
        if s[0] != "0":
            words.append(self.NUMBER[int(s[0])])
            words.append("HUNDRED")
            if s[1:] != "00":
                words.append("AND")
        if s[1:] != "00":
            words.append(self.trans_two(s[1:]))
        return " ".join([w for w in words if w])

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        """
        if i < len(self.NUMBER_MORE):
            return self.NUMBER_MORE[i]
        else:
            return ""

    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        """
        # Handle negative numbers
        negative = False
        if isinstance(x, str):
            x = x.strip()
            if x.startswith('-'):
                negative = True
                x = x[1:]
            try:
                x = float(x) if '.' in x else int(x)
            except:
                return "INVALID INPUT"
        else:
            if x < 0:
                negative = True
                x = -x

        if isinstance(x, float):
            int_part = int(x)
            dec_str = str(x).split(".")[1]
        else:
            int_part = x
            dec_str = ""

        if int_part == 0:
            int_words = "ZERO"
        else:
            s = str(int_part)
            groups = []
            while s:
                groups.append(s[-3:].rjust(3, "0"))
                s = s[:-3]
            words = []
            for i, group in enumerate(groups):
                w = self.trans_three(group)
                if w:
                    suffix = self.parse_more(i)
                    if suffix:
                        w = w + " " + suffix
                    words.append(w)
            int_words = " ".join(reversed(words)).strip()

        # Decimal part
        if dec_str and int(dec_str) != 0:
            dec_words = "POINT " + " ".join(self.NUMBER[int(d)] for d in dec_str)
        else:
            dec_words = ""

        result = ""
        if negative:
            result += "MINUS "
        result += int_words
        if dec_words:
            result += " " + dec_words
        result = result.strip() + " ONLY"
        return result

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        """
        x = x.strip()
        if not x:
            return "INVALID INPUT"
        try:
            if '.' in x:
                num = float(x)
            else:
                num = int(x)
        except:
            return "INVALID INPUT"
        return self.format(num)

