                    codepoint = int(entity, 10)
                # Only replace if codepoint is valid Unicode scalar value
                if 0 <= codepoint <= 0x10FFFF:
                    return chr(codepoint)
            except Exception:
                pass
            # If anything fails, return the original match
            return match.group(0)

        return pattern.sub(repl, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        return char in '0123456789abcdefABCDEF'

class PushBoxGame:
    """
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    """

    def __init__(self, map):
        """
        Initialize the push box game with the map and various attributes.
        """
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        """
        Initialize the game by setting the positions of the player, targets, and boxes based on the map.
        """
        self.targets = []
        self.boxes = []
        self.player_row = -1
        self.player_col = -1
        for r, row in enumerate(self.map):
            for c, ch in enumerate(row):
                if ch == 'O':
                    self.player_row, self.player_col = r, c
                elif ch == 'G':
                    self.targets.append((r, c))
                elif ch == 'X':
                    self.boxes.append((r, c))
        self.target_count = len(self.targets)
        self.is_game_over = False

    def check_win(self):
        """
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of self.is_game_over.
        """
        # Win if every box is on a target
        win = all(box in self.targets for box in self.boxes)
        self.is_game_over = win
        return win

    def move(self, direction):
        """
        Move the player based on the specified direction and check if the game is won.
        """
        if self.is_game_over:
            return True

        dir_map = {
            'w': (-1, 0),
            's': (1, 0),
            'a': (0, -1),
            'd': (0, 1)
        }
        if direction not in dir_map:
            return self.check_win()

        dr, dc = dir_map[direction]
        pr, pc = self.player_row, self.player_col
        nr, nc = pr + dr, pc + dc  # next position

        # Check bounds
        if not (0 <= nr < len(self.map) and 0 <= nc < len(self.map[0])):
            return self.check_win()

        dest_char = self.map[nr][nc]
        box_positions = set(self.boxes)

        # If next cell is wall, can't move
        if dest_char == '#':
            return self.check_win()

        # If next cell is box
        if (nr, nc) in box_positions:
            # Try to push box
            br, bc = nr + dr, nc + dc  # box's next position
            # Check bounds
            if not (0 <= br < len(self.map) and 0 <= bc < len(self.map[0])):
                return self.check_win()
            box_dest_char = self.map[br][bc]
            # Can't push into wall or another box
            if box_dest_char == '#' or (br, bc) in box_positions:
                return self.check_win()
            # Move box
            self.boxes = [
                (br, bc) if (r, c) == (nr, nc) else (r, c)
                for (r, c) in self.boxes
            ]
            # Move player
            self.player_row, self.player_col = nr, nc
        else:
            # Move player if not wall or box
            self.player_row, self.player_col = nr, nc

        return self.check_win()

    def print_map(self):
        """
        Print the current map with updated positions.
        """
        # Build a grid from the original map
        grid = [list(row) for row in self.map]
        # Clear player, boxes, targets from grid
        for r, row in enumerate(grid):
            for c, ch in enumerate(row):
                if ch in 'OXG':
                    if (r, c) in self.targets:
                        grid[r][c] = 'G'
                    else:
                        grid[r][c] = ' '
        # Place boxes
        for r, c in self.boxes:
            if (r, c) in self.targets:
                grid[r][c] = 'X'  # Could use '*' for box on target
            else:
                grid[r][c] = 'X'
        # Place player
        pr, pc = self.player_row, self.player_col
        if (pr, pc) in self.targets:
            grid[pr][pc] = 'O'  # Could use different symbol for player on target
        else:
            grid[pr][pc] = 'O'
        # Print
        for row in grid:
            print(' '.join(row))

class ShoppingCart:
    """
    The class manages items, their prices, quantities, and allows to for add, remove, view items, and calculate the total price.
    """

    def __init__(self):
        """
        Initialize the items representing the shopping list as an empty dictionary
        """
        self.items = {}

    def add_item(self, item, price, quantity=1):
        """
        Add item information to the shopping list items, including price and quantity. The default quantity is 1
        :param item: string, Item to be added
        :param price: float, The price of the item
        :param quantity:int, The number of items, defaults to 1
        :return:None
        """
        if not isinstance(item, str) or not item:
            raise ValueError("Item name must be a non-empty string.")
        if not isinstance(price, (int, float)) or price <= 0:
            raise ValueError("Price must be a positive number.")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")

        if item in self.items:
            # Update price and add quantity
            self.items[item]['price'] = price
            self.items[item]['quantity'] += quantity
        else:
            self.items[item] = {'price': price, 'quantity': quantity}

    def remove_item(self, item, quantity=1):
        """
        Subtract the specified quantity of item from the shopping list items
        :param item:string, Item to be subtracted in quantity
        :param quantity:int, Quantity to be subtracted
        :return:None
        """
        if not isinstance(item, str) or not item:
            raise ValueError("Item name must be a non-empty string.")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be a positive integer.")

        if item not in self.items:
            raise KeyError(f"Item '{item}' not found in cart.")

        current_quantity = self.items[item]['quantity']
        if quantity >= current_quantity:
            # Remove item entirely
            del self.items[item]
        else:
            self.items[item]['quantity'] -= quantity

    def view_items(self) -> dict:
        """
        Return the current shopping list items
        :return:dict, the current shopping list items
        """
        # Return a deep copy to prevent external modification
        return {item: {'price': info['price'], 'quantity': info['quantity']} for item, info in self.items.items()}

    def total_price(self) -> float:
        """
        Calculate the total price of all items in the shopping list, which is the quantity of each item multiplied by the price
        :return:float, the total price of all items in the shopping list
        """
        total = 0.0
        for info in self.items.values():
            total += info['price'] * info['quantity']
        return total

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _quote(value):
        """
        Quote the value for SQL. Always use single quotes, even for numbers.
        """
        return f"'{value}'"

    @staticmethod
    def _build_where(where):
        """
        Build the WHERE clause from a dict.
        """
        if not where:
            return ''
        conditions = [f"{k}={SQLQueryBuilder._quote(v)}" for k, v in where.items()]
        return " WHERE " + " AND ".join(conditions)

    @staticmethod
    def select(table, columns='*', where=None):
        """
        Generate the SELECT SQL statement from the given parameters.
        """
        if columns == '*' or columns is None:
            cols = '*'
        elif isinstance(columns, list):
            cols = ', '.join(columns)
        else:
            cols = str(columns)
        query = f"SELECT {cols} FROM {table}"
        where_clause = SQLQueryBuilder._build_where(where)
        query += where_clause
        return query

    @staticmethod
    def insert(table, data):
        """
        Generate the INSERT SQL statement from the given parameters.
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for insert must be a non-empty dict")
        columns = ', '.join(data.keys())
        values = ', '.join([SQLQueryBuilder._quote(v) for v in data.values()])
        query = f"INSERT INTO {table} ({columns}) VALUES ({values})"
        return query

    @staticmethod
    def delete(table, where=None):
        """
        Generate the DELETE SQL statement from the given parameters.
        """
        query = f"DELETE FROM {table}"
        where_clause = SQLQueryBuilder._build_where(where)
        query += where_clause
        return query

    @staticmethod
    def update(table, data, where=None):
        """
        Generate the UPDATE SQL statement from the given parameters.
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for update must be a non-empty dict")
        set_clause = ', '.join([f"{k}={SQLQueryBuilder._quote(v)}" for k, v in data.items()])
        query = f"UPDATE {table} SET {set_clause}"
        where_clause = SQLQueryBuilder._build_where(where)
        query += where_clause
        return query

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            if word:  # skip empty strings for 0, 1
                self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def _normalize(self, textnum):
        """
        Helper to normalize input: lowercase, replace hyphens with spaces, strip.
        """
        return textnum.lower().replace('-', ' ').strip()

    def _split_words(self, textnum):
        """
        Helper to split input into words, handling hyphens and spaces.
        """
        return self._normalize(textnum).split()

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        True
        """
        words = self._split_words(textnum)
        for word in words:
            if word in self.numwords:
                continue
            if word in self.ordinal_words:
                continue
            # Try to convert ordinal endings to cardinal
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    base = word[:-len(ending)] + replacement
                    if base in self.numwords:
                        break
            else:
                # Not found in any dictionary
                return False
        return True

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        words = self._split_words(textnum)
        if not words:
            raise ValueError("Input is empty or invalid.")

        current = result = 0
        last_scale = 1
        for word in words:
            if word in self.numwords:
                scale, increment = self.numwords[word]
            elif word in self.ordinal_words:
                scale, increment = (1, self.ordinal_words[word])
            else:
                # Try to convert ordinal endings to cardinal
                for ending, replacement in self.ordinal_endings:
                    if word.endswith(ending):
                        base = word[:-len(ending)] + replacement
                        if base in self.numwords:
                            scale, increment = self.numwords[base]
                            break
                else:
                    raise ValueError(f"Invalid word: {word}")

            if scale > 1:
                if current == 0:
                    current = 1
                current = current * scale
                last_scale = scale
            else:
                current = current + increment

            # If scale is 1000 or more, add to result and reset current
            if scale >= 1000:
                result += current
                current = 0

        total = result + current
        return str(total)
